<?php $this->assign('title', 'Vendas'); ?><div class="d-flex justify-content-between mb-4"><h1 class="h3">Vendas</h1><?= $this->Html->link('Venda rápida', ['action' => 'add'], ['class' => 'btn btn-primary']) ?></div><div class="card border-0 shadow-sm"><table class="table table-hover mb-0"><thead><tr><th>Número</th><th>Data</th><th>Cliente</th><th>Status</th><th>Total</th></tr></thead><tbody><?php foreach ($vendas as $venda): ?><tr><td><?= $this->Html->link($venda->numero, ['action' => 'view', $venda->id]) ?></td><td><?= h($venda->created->format('d/m/Y H:i')) ?></td><td><?= h($venda->cliente->nome ?? 'Consumidor') ?></td><td><?= h($venda->status) ?></td><td>R$ <?= number_format((float)$venda->total, 2, ',', '.') ?></td></tr><?php endforeach; ?></tbody></table></div>
